import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Is Clash compatible with Quantumult X?","description":"How to move Quantumult X subscriptions, nodes, policies, rewrites and filtering needs to Clash for iOS.","frontmatter":{"title":"Is Clash compatible with Quantumult X?","description":"How to move Quantumult X subscriptions, nodes, policies, rewrites and filtering needs to Clash for iOS.","head":[["meta",{"name":"keywords","content":"Quantumult X to Clash,QuanX subscription,Quantumult X config,Clash iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move a Quantumult X configuration to Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Start with a Clash / mihomo subscription from the provider, or organize node parameters as mihomo YAML or add them in the node editor. Recreate policies, rewrites and filtering needs with Clash rules and matching features.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"Can I use a Quantumult X subscription in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes when the provider returns mihomo YAML from an HTTPS subscription URL. Standalone node parameters can also be organized as YAML or entered manually.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility/quantumult-x.md","filePath":"guide/compatibility/quantumult-x.md","lastUpdated":1785318168000}`),a={name:`guide/compatibility/quantumult-x.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="is-clash-compatible-with-quantumult-x" tabindex="-1">Is Clash compatible with Quantumult X? <a class="header-anchor" href="#is-clash-compatible-with-quantumult-x" aria-label="Permalink to “Is Clash compatible with Quantumult X?”">​</a></h1><p><strong>Common nodes continue to work, while routing policies can be recreated with Clash rules.</strong></p><p>Quantumult X uses its own <a href="https://github.com/crossutility/Quantumult-X/blob/master/sample.conf" target="_blank" rel="noreferrer">configuration and resource syntax</a>. When moving to Clash, keep using nodes through subscriptions, mihomo YAML or the node editor, then recreate policies, rewrites, scripts and filtering needs with matching features.</p><h2 id="what-can-be-reused" tabindex="-1">What can be reused? <a class="header-anchor" href="#what-can-be-reused" aria-label="Permalink to “What can be reused?”">​</a></h2><ul><li>subscription URLs that can return mihomo YAML;</li><li>the node parameters contained in <code>ss://</code>, <code>ssr://</code>, <code>vmess://</code>, and similar share links, after conversion to mihomo YAML or manual entry;</li><li>servers that can be recreated from their parameters in the Clash node editor.</li></ul><h2 id="how-to-migrate" tabindex="-1">How to migrate <a class="header-anchor" href="#how-to-migrate" aria-label="Permalink to “How to migrate”">​</a></h2><ol><li>Select a Clash / mihomo subscription format from the provider.</li><li>Add that URL to Clash; change the subscription User-Agent when necessary.</li><li>Organize parameters from standalone share links or Base64 lists as mihomo YAML, or add them in the node editor.</li><li>Express the original routing intent using Clash rules.</li></ol><h2 id="what-to-configure-during-migration" tabindex="-1">What to configure during migration <a class="header-anchor" href="#what-to-configure-during-migration" aria-label="Permalink to “What to configure during migration”">​</a></h2><ul><li>organize nodes and policies as mihomo YAML;</li><li>recreate rewrite, filter, task and script needs with matching Clash features;</li><li>express product-specific resource syntax with Clash rules;</li><li>set app preferences to match your workflow.</li></ul><p>The same server can be used directly once its protocol and parameters match.</p><p>Return to the <a href="/clash.md/guide/compatibility">compatibility overview</a>.</p>`,11)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};